 if(typeof window.playExtraCard==='function'&&!String(window.playExtraCard).includes('LV3360_CARD')){let base=window.playExtraCard;window.playExtraCard=function(c){/* LV3360_CARD */let h=controlledHero(),x=hs(h),beforeA=heroActionCount(h),isSpell=h==='Vaelis'&&/Spell/i.test(String(c?.traits||''));let oldCost=c?.cost,parallel=false;if(isSpell&&lvl(h)>=14&&x.round.firstSpellRound===g.round&&x.round.firstSpellName!==c.name&&x.round.parallelUsed!==g.round){c.cost=Math.max(0,Number(c.cost||0)-1);parallel=true}let r;try{r=base.apply(this,arguments)}finally{if(c)c.cost=oldCost}let spent=heroActionCount(h)<beforeA;if(spent){x.round.actionTypes=x.round.actionTypes||[];let arr=Array.isArray(x.round.actionTypes)?x.round.actionTypes:[...x.round.actionTypes];if(!arr.includes(c.category||'Card'))arr.push(c.category||'Card');x.round.actionTypes=arr;if(isSpell){if(x.round.firstSpellRound!==g.round){x.round.firstSpellRound=g.round;x.round.firstSpellName=c.name}else if(parallel){x.round.parallelUsed=g.round;logL('Parallel Casting: second different Spell cost 1 fewer Action.')}if(lvl(h)>=13&&x.round.arcaneSov!==g.round){x.round.arcaneSov=g.round;logL('Arcane Sovereignty: Arcane prerequisite may be treated as satisfied for this Spell.')}if(lvl(h)>=16&&x.buff.masterRealityRound===g.round&&Number(x.buff.masterRealityCopies||0)<3&&c.speed!=='Reaction'){x.buff.masterRealityCopies=(x.buff.masterRealityCopies||0)+1;let s=runtimeHeroState(h);if(s){let echo={...c,uid:(c.uid||c.id)+'-echo3360-'+x.buff.masterRealityCopies,name:'Echo: '+c.name,cost:0,_free3360:true};s.hand.push(echo);logL(`Master of Reality: a free echo of ${c.name} is added to Vaelis's hand.`)}}}if(x.buff.songReturnRound===g.round&&!x.buff.songReturned){x.buff.songReturned=true;let hand=runtimeHeroState(h)?.hand,disc=runtimeHeroState(h)?.discard,idx=disc?.findIndex(z=>(z.uid||z.id)===(c.uid||c.id));if(idx>=0){let z=disc.splice(idx,1)[0];hand.push(z);logL(`Song That Remains: ${c.name} returns to ${heroDisplayName(h)}'s hand.`)}}if(c?._free3360){let s=runtimeHeroState(h);s.actions=Math.min(3,s.actions+(beforeA-heroActionCount(h)));let di=s.discard.findIndex(z=>z.uid===c.uid);if(di>=0)s.discard.splice(di,1);logL(`Master of Reality echo resolves for 0 Actions.`)}}return r}}
