function installActionTracking(){for(const name of ['attack','explore','search','runtimeHeroMove']){let old=window[name];if(typeof old!=='function'||String(old).includes('LV3360_TRACK'))continue;window[name]=function(){/* LV3360_TRACK */let h=controlledHero(),a=heroActionCount(h),p=pos(h),r=old.apply(this,arguments),after=heroActionCount(h),p2=pos(h);if(after<a||p.x!==p2.x||p.y!==p2.y){let x=hs(h),type=name==='runtimeHeroMove'?'Move':name[0].toUpperCase()+name.slice(1);let arr=Array.isArray(x.round.actionTypes)?x.round.actionTypes:[];if(!arr.includes(type))arr.push(type);x.round.actionTypes=arr}return r}}
}
function abilityMeta(h,L){return META?.[h]?.[L]||{kind:'passive'}}
function abilityState(h,L){
 let m=abilityMeta(h,L),x=hs(h),status='PASSIVE',ready=false,usedNow=false;
 if(m.kind==='passive')return{...m,status,ready:false,used:false,type:'PASSIVE'};
 if(m.kind==='quest-choice')return{...m,status:x.buff?.blueprint?'PASSIVE':'READY',ready:!x.buff?.blueprint,used:!!x.buff?.blueprint,type:'QUEST CHOICE'};
 if(m.kind.endsWith('-round')){usedNow=x.round?.[m.roundKey]===g.round;status=usedNow?'USED THIS ROUND':'READY';ready=!usedNow;return{...m,status,ready,used:usedNow,type:m.kind.startsWith('active')?'ACTIVATED':'TRIGGERED'}}
 if(m.kind.endsWith('-quest')){usedNow=used(h,m.usedKey??L);status=usedNow?'USED THIS QUEST':'READY';ready=!usedNow;return{...m,status,ready,used:usedNow,type:m.kind.startsWith('active')?'ACTIVATED':'TRIGGERED'}}
 return{...m,status:'PASSIVE',ready:false,used:false,type:'PASSIVE'}
}
function statusStyle(st){
 if(st.status==='PASSIVE')return'background:#263b2a;color:#bfe6b8;border-color:#4f7b56';
 if(st.status==='READY')return'background:#3a2d0f;color:#ffd976;border-color:#a47b2a';
 if(st.status==='USED THIS ROUND')return'background:#263546;color:#a9c9eb;border-color:#466787';
 return'background:#3b2525;color:#e8b0a8;border-color:#7a4747';
}
function renderPanel(){
 let old=document.getElementById('levelAbilities3360');
 if(!g||!document.getElementById('partyPanel')){old?.remove();return}
 let h=controlledHero();
 if(!AB[h]||lvl(h)<13){old?.remove();return}
 if(!old){old=document.createElement('div');old.id='levelAbilities3360';old.className='panel';old.style.cssText='margin-top:10px;border:1px solid #9a7838;background:linear-gradient(180deg,rgba(35,25,12,.96),rgba(15,12,8,.96));';document.getElementById('partyPanel').after(old)}
 let rows=[];
 for(let L=13;L<=16;L++){
  if(lvl(h)<L)continue;
  let [nm,tx]=AB[h][L],stt=abilityState(h,L),clickable=stt.type==='ACTIVATED',disabled=clickable&&!stt.ready;
  let timing=stt.type==='PASSIVE'?'Always active':stt.type==='TRIGGERED'?'Triggers automatically; prompts when a choice is required':stt.type==='QUEST CHOICE'?'Chosen at Quest start':(Number(stt.cost||0)>0?`${stt.cost} Action${Number(stt.cost||0)===1?'':'s'} to activate`:'Activate when legal');
  let control=clickable?`<button data-lv3360="${L}" ${disabled?'disabled':''}>${disabled?stt.status:(Number(stt.cost||0)>0?`Activate · ${stt.cost} Action${Number(stt.cost||0)===1?'':'s'}`:'Activate Ability')}</button>`:`<span class="muted" style="font-size:11px">${timing}</span>`;
  rows.push(`<div class="lvAbilityRow3360" data-lv-row="${L}" style="padding:8px 0;border-bottom:1px solid rgba(180,140,70,.25)"><div style="display:flex;gap:7px;align-items:center;justify-content:space-between;flex-wrap:wrap"><b>Lv ${L} — ${nm}</b><span data-lv-state="${L}" style="font-size:10px;font-weight:800;letter-spacing:.04em;padding:3px 7px;border:1px solid;border-radius:999px;${statusStyle(stt)}">${stt.status}</span></div><div class="muted" style="margin:4px 0 6px">${tx}</div><div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><span style="font-size:10px;letter-spacing:.05em;color:#d7bd7a;font-weight:700">${stt.type}</span>${control}</div></div>`)
 }
 old.innerHTML=`<div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><div><b style="color:#f0cf79">HERO ABILITIES</b><div class="muted">${heroDisplayName(h)} · Level ${lvl(h)}</div></div><div style="font-size:10px;color:#b8a67d;text-align:right">PASSIVE · READY<br/>ROUND / QUEST tracking</div></div>${rows.join('')}<div style="margin-top:6px;font-size:11px;color:#b8a67d">Triggered abilities resolve automatically or prompt when a choice is required. Activated abilities use the button above. · v${V}</div>`;
 old.querySelectorAll('[data-lv3360]').forEach(b=>b.onclick=()=>{useAbility(h,Number(b.dataset.lv3360));try{renderPanel()}catch(_){}})
}

function renderPieces(){document.querySelectorAll('.lvPiece3360').forEach(e=>e.remove());for(const c of root().constructs||[]){let t=g.tiles?.[c.k];if(!t)continue;let el=[...document.querySelectorAll('.tile')].find(e=>e.dataset?.id===t.id||e.querySelector('.tname')?.textContent?.startsWith(t.name));if(el){let d=document.createElement('div');d.className='lvPiece3360';d.style.cssText='margin-top:3px;text-align:center;color:#f0cf79;font-weight:700';d.textContent=`⚙ Grand Construct ${c.hp}/${c.maxHp}`;el.appendChild(d)}}for(const [k,type] of Object.entries(root().nature||{})){let t=g.tiles?.[k];if(!t)continue;let el=[...document.querySelectorAll('.tile')].find(e=>e.dataset?.id===t.id||e.querySelector('.tname')?.textContent?.startsWith(t.name));if(el){let d=document.createElement('div');d.className='lvPiece3360';d.style.cssText='margin-top:3px;text-align:center;color:#9bd18b;font-weight:700';d.textContent=type==='Worldroot'?'🌳 Worldroot':'🌿 Nature';el.appendChild(d)}}}
function roundStart(){let r=root();if(r.round===g.round)return;r.round=g.round;r.roundStart={};for(const h of partyHeroes()){r.roundStart[h]={...pos(h)};let x=hs(h);x.round={};x.turnStart=x.turnStart||{};x.turnStart[h]={...pos(h)};if(h==='Mira'&&lvl(h)>=14&&!x.buff.blueprint){let ch=prompt('Adaptive Blueprint — choose offense, defense, or support for this Quest.','offense')||'offense';x.buff.blueprint=/def/i.test(ch)?'defense':/sup/i.test(ch)?'support':'offense';logL('Adaptive Blueprint: '+x.buff.blueprint+'.')}if(h==='Seraphine'&&lvl(h)>=13){setTimeout(()=>{if(isPartyHero(h)&&!heroDefeated(h)&&g?.phase==='Hero Phase'&&hs(h).round.banner!==g.round){}},0)}if(h==='Asha'&&lvl(h)>=16&&x.buff.voiceRound===g.round)for(const k of totemKeys())triggerTotem(k,'Voice Beyond Veil — round start')}
}
function installRender(){if(typeof window.render==='function'&&!String(window.render).includes('LV3360_RENDER')){let base=window.render;window.render=function(){/* LV3360_RENDER */let r=base.apply(this,arguments);try{roundStart();renderPanel();renderPieces()}catch(e){console.warn('3360 level render',e)}return r}}}
